#include <stdio.h>
#include <stdlib.h>

void leaky() {
    int *p = malloc(1000);  // 1000 바이트 할당
    *p = 42;
    // free(p);  // 실수로 누락!
}  // p는 사라지지만 Heap 메모리는 남음

int main() {
    for (int i = 0; i < 1000; i++) {
        leaky();  // 매번 1KB 누수!
    }
    // 약 1MB 메모리 누수 발생
    printf("프로그램 종료\n");
    return 0;
}
